// Helper: Filter destinations by state ID
export function getDestinationsByState(stateId) {
  if (!stateId || stateId === "all") return MASTER_EXPLORER_DESTINATIONS;
  return MASTER_EXPLORER_DESTINATIONS.filter(d => d.stateId === stateId);
}

// Helper: Filter destinations by category
export function getDestinationsByCategory(categoryId) {
  if (!categoryId || categoryId === "all") return MASTER_EXPLORER_DESTINATIONS;
  return MASTER_EXPLORER_DESTINATIONS.filter(d => 
    d.category === categoryId || (d.categories && d.categories.includes(categoryId))
  );
}

// Helper: Search destinations by text (name, deity, location, state, overview)
export function searchDestinations(query, destinations = MASTER_EXPLORER_DESTINATIONS) {
  if (!query || !query.trim()) return destinations;
  const q = query.toLowerCase().trim();
  return destinations.filter(d => 
    d.name.toLowerCase().includes(q) ||
    d.title.toLowerCase().includes(q) ||
    (d.deity && d.deity.toLowerCase().includes(q)) ||
    (d.state && d.state.toLowerCase().includes(q)) ||
    (d.location && d.location.toLowerCase().includes(q)) ||
    (d.category && d.category.toLowerCase().includes(q))
  );
}

// High-Precision Multi-Field & Alias Search for Destination Selection
export function searchSavedDestinationsDatabase(query, destinations = MASTER_EXPLORER_DESTINATIONS) {
  if (!query || !query.trim()) return [];
  const cleanQ = query.trim().toLowerCase();
  
  const ALIAS_MAP = {
    ujjain: ["ujjain", "ujjaini", "avanti", "avantika", "mahakal"],
    varanasi: ["varanasi", "kashi", "banaras", "benares", "vishwanath"],
    barsana: ["barsana", "radha rani", "radharani", "ladli ji", "shriji", "bhanukhar"],
    vrindavan: ["vrindavan", "brindavan", "banke bihari", "bihari ji", "nidhivan", "prem mandir"],
    puri: ["puri", "jagannath", "jagannath puri", "srikkshetra"],
    khatu: ["khatu", "khatu shyam", "khatushyam", "shyam baba"],
    prayagraj: ["prayagraj", "allahabad", "prayag", "triveni", "sangam"],
    ayodhya: ["ayodhya", "saket", "faizabad", "ram janmabhoomi", "ram mandir"],
    haridwar: ["haridwar", "hardwar", "gangadwar", "har ki pauri"],
    rishikesh: ["rishikesh", "hrishikesh"],
    mathura: ["mathura", "vrindavan", "braj", "barsana", "gokul"],
    dwarka: ["dwarka", "dwaraka", "dwarkadhish"],
    somnath: ["somnath", "prabhas patan"],
    kedarnath: ["kedarnath", "kedar"],
    badrinath: ["badrinath", "badri"],
    tirupati: ["tirupati", "tirumala", "balaji", "venkateswara"],
    madurai: ["madurai", "meenakshi"],
    rameshwaram: ["rameshwaram", "rameshwar", "sethu"],
    shirdi: ["shirdi", "sai baba"],
    amritsar: ["amritsar", "golden temple", "harmandir"],
    delhi: ["delhi", "new delhi"]
  };

  let aliasTokens = [cleanQ];
  for (const [key, aliases] of Object.entries(ALIAS_MAP)) {
    if (aliases.some(a => cleanQ === a || cleanQ.includes(a) || a.includes(cleanQ))) {
      aliasTokens = [...new Set([...aliasTokens, key, ...aliases])];
    }
  }

  const matches = [];
  const seenIds = new Set();
  const seenNames = new Set();

  for (const place of destinations) {
    if (!place || !place.id || seenIds.has(place.id)) continue;

    const name = (place.name || "").toLowerCase();
    const title = (place.title || "").toLowerCase();
    const city = (place.city || "").toLowerCase();
    const district = (place.district || "").toLowerCase();
    const location = (place.location || "").toLowerCase();
    const state = (place.state || "").toLowerCase();
    const deity = (place.deity || "").toLowerCase();
    const badge = (place.badge || "").toLowerCase();
    const cat = (place.categoryLabel || place.category || "").toLowerCase();

    let score = 0;

    if (name === cleanQ || city === cleanQ) {
      score += 120;
    } else if (name.startsWith(cleanQ) || city.startsWith(cleanQ)) {
      score += 85;
    } else if (name.includes(cleanQ)) {
      score += 65;
    } else if (city.includes(cleanQ)) {
      score += 55;
    } else if (location.includes(cleanQ) || district.includes(cleanQ)) {
      score += 40;
    } else if (state.includes(cleanQ)) {
      score += 25;
    } else if (deity.includes(cleanQ) || badge.includes(cleanQ) || cat.includes(cleanQ)) {
      score += 20;
    }

    for (const token of aliasTokens) {
      if (token.length < 3) continue;
      const regex = new RegExp("\\b" + token + "\\b", "i");
      if (regex.test(name) || regex.test(city) || regex.test(location) || regex.test(district)) {
        score += 45;
        break;
      }
    }

    if (score > 0) {
      const normKey = (place.name || "").replace(/^(Shri|Maa|Lord|Sri)\s+/i, "").toLowerCase().trim();
      if (seenNames.has(normKey)) {
        continue;
      }
      seenNames.add(normKey);
      seenIds.add(place.id);
      matches.push({ place, score });
    }
  }

  matches.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    if (b.place.popular && !a.place.popular) return 1;
    if (!b.place.popular && a.place.popular) return -1;
    return a.place.name.localeCompare(b.place.name);
  });

  return matches.slice(0, 20).map(m => m.place);
}

// Natural Language Query Interpreter
export function interpretNaturalSearchQuery(query, availableDestinations = MASTER_EXPLORER_DESTINATIONS) {
  if (!query || !query.trim()) return null;
  const q = query.toLowerCase().trim();

  // 1. Detect Multi-Stop Trip Intent
  // e.g. "Plan a trip from Varanasi to Ayodhya, Prayagraj and Lucknow"
  // e.g. "Trip from Delhi to Haridwar, Rishikesh"
  const tripMatch = q.match(/(?:plan\s+(?:a\s+)?trip|route|journey)\s+from\s+([a-z\s]+?)\s+to\s+([a-z\s,]+)/i);
  if (tripMatch) {
    const originRaw = tripMatch[1].trim();
    const stopsRaw = tripMatch[2].trim();
    const stopTokens = stopsRaw.split(/[,&]|\band\b/).map(s => s.trim()).filter(Boolean);

    // Find matching destinations in registry
    const matchedStops = [];
    stopTokens.forEach(token => {
      const found = availableDestinations.find(d => 
        d.name.toLowerCase().includes(token) || 
        d.location.toLowerCase().includes(token) ||
        (d.city && d.city.toLowerCase().includes(token))
      );
      if (found && !matchedStops.some(s => s.id === found.id)) {
        matchedStops.push(found);
      }
    });

    return {
      type: "trip_plan",
      rawQuery: query,
      originQuery: originRaw,
      stopNames: stopTokens,
      matchedStops: matchedStops,
      message: `Planned multi-stop trip with ${matchedStops.length} stops`
    };
  }

  // 2. Detect State Mentions
  const STATE_KEYWORDS = [
    { id: "uttarakhand", keys: ["uttarakhand", "uttaranchal"] },
    { id: "himachal_pradesh", keys: ["himachal", "himachal pradesh", "hp"] },
    { id: "uttar_pradesh", keys: ["uttar pradesh", "up"] },
    { id: "maharashtra", keys: ["maharashtra", "bombay", "mumbai"] },
    { id: "tamil_nadu", keys: ["tamil nadu", "tamilnadu", "tn"] },
    { id: "rajasthan", keys: ["rajasthan"] },
    { id: "karnataka", keys: ["karnataka", "bangalore", "bengaluru"] },
    { id: "madhya_pradesh", keys: ["madhya pradesh", "mp"] },
    { id: "bihar", keys: ["bihar"] },
    { id: "west_bengal", keys: ["west bengal", "bengal", "kolkata"] },
    { id: "andhra_pradesh", keys: ["andhra pradesh", "andhra", "ap"] },
    { id: "gujarat", keys: ["gujarat"] },
    { id: "odisha", keys: ["odisha", "orissa"] },
    { id: "assam", keys: ["assam"] },
    { id: "kerala", keys: ["kerala"] },
    { id: "jammu_kashmir", keys: ["jammu and kashmir", "jammu & kashmir", "kashmir", "jammu"] },
    { id: "ladakh", keys: ["ladakh", "leh"] },
    { id: "goa", keys: ["goa"] },
    { id: "punjab", keys: ["punjab", "amritsar"] },
    { id: "haryana", keys: ["haryana", "kurukshetra"] },
    { id: "jharkhand", keys: ["jharkhand", "deoghar"] },
    { id: "chhattisgarh", keys: ["chhattisgarh", "bastar"] },
    { id: "telangana", keys: ["telangana", "hyderabad"] },
    { id: "tripura", keys: ["tripura"] },
    { id: "meghalaya", keys: ["meghalaya", "shillong", "cherrapunji"] },
    { id: "delhi", keys: ["delhi", "new delhi"] },
    { id: "chandigarh", keys: ["chandigarh"] },
    { id: "sikkim", keys: ["sikkim", "gangtok"] },
    { id: "arunachal_pradesh", keys: ["arunachal", "tawang"] },
    { id: "puducherry", keys: ["puducherry", "pondicherry"] },
    { id: "andaman_nicobar", keys: ["andaman", "nicobar", "port blair", "havelock"] }
  ];

  let detectedStateId = null;
  let detectedStateName = "";
  for (const st of STATE_KEYWORDS) {
    if (st.keys.some(k => q.includes(k))) {
      detectedStateId = st.id;
      detectedStateName = st.keys[0];
      break;
    }
  }

  // 3. Detect Category Mentions
  const detectedCategories = [];
  if (q.includes("jyotirlinga") || q.includes("jyotirlingas")) detectedCategories.push("jyotirlingas");
  if (q.includes("shaktipeeth") || q.includes("shaktipeeths") || q.includes("shakti peeth")) detectedCategories.push("shaktipeeths");
  if (q.includes("chardham") || q.includes("char dham") || q.includes("dham")) detectedCategories.push("chardham");
  if (q.includes("mountain") || q.includes("mountains") || q.includes("hill") || q.includes("hills") || q.includes("trek") || q.includes("pass")) detectedCategories.push("mountains");
  if (q.includes("lake") || q.includes("lakes") || q.includes("waterfall") || q.includes("waterfalls") || q.includes("river") || q.includes("cascade")) detectedCategories.push("lakes_waterfalls");
  if (q.includes("beach") || q.includes("beaches") || q.includes("coast") || q.includes("coastal")) detectedCategories.push("beaches_coastal");
  if (q.includes("heritage") || q.includes("fort") || q.includes("forts") || q.includes("palace") || q.includes("monument") || q.includes("unesco") || q.includes("ruins")) detectedCategories.push("heritage_history");
  if (q.includes("wildlife") || q.includes("safari") || q.includes("national park")) detectedCategories.push("wildlife_nature");
  if (q.includes("temple") || q.includes("temples") || q.includes("mandir") || q.includes("pilgrimage") || q.includes("shrine")) {
    if (!detectedCategories.includes("jyotirlingas") && !detectedCategories.includes("shaktipeeths")) {
      detectedCategories.push("temples");
    }
  }

  // Detect Railway Stations request
  const showStations = q.includes("railway") || q.includes("station") || q.includes("stations") || q.includes("train");

  if (detectedStateId || detectedCategories.length > 0 || showStations) {
    let summaryParts = [];
    if (detectedStateId) summaryParts.push(`State: ${detectedStateId.replace('_', ' ').toUpperCase()}`);
    if (detectedCategories.length > 0) summaryParts.push(`Categories: ${detectedCategories.join(', ')}`);
    if (showStations) summaryParts.push("Railway Stations Layer Enabled");

    return {
      type: "filter",
      rawQuery: query,
      stateId: detectedStateId,
      categories: detectedCategories,
      showStations: showStations,
      message: summaryParts.join(" • ")
    };
  }

  return null;
}
